import React, { useState, useEffect, useMemo, useCallback } from "react";
import {
  LayoutDashboard, FileText, Users, Settings as SettingsIcon, LogOut,
  Plus, Search, Printer, Trash2, X, Moon, Sun, ArrowRight,
  Pencil, Send, CheckCircle2, ChevronLeft
} from "lucide-react";
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid
} from "recharts";
import { supabase } from "./lib/supabaseClient";
import { loadAppData, createAppData, saveAppData } from "./lib/appData";

/* ------------------------------------------------------------------ */
/* Constants & helpers                                                 */
/* ------------------------------------------------------------------ */

const CURRENCIES = { INR: "₹", USD: "$", EUR: "€", GBP: "£", JPY: "¥" };
const LOGO_URL =
  "data:image/jpeg;base64,";

const STATUS_META = {
  draft: { label: "Draft", dot: "var(--muted)" },
  sent: { label: "Sent", dot: "var(--pine-light)" },
  paid: { label: "Paid", dot: "var(--good)" },
  overdue: { label: "Overdue", dot: "var(--rust)" },
};

const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36);

const todayISO = () => new Date().toISOString().slice(0, 10);

const addDays = (isoDate, days) => {
  const d = new Date(isoDate);
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
};

const fmtDate = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
};

const fmtMoney = (amount, currency) => {
  const sym = CURRENCIES[currency] || "$";
  const n = Number(amount) || 0;
  const locale = currency === "INR" ? "en-IN" : undefined;
  return `${sym}${n.toLocaleString(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

const computeTotals = (inv) => {
  const subtotal = (inv.items || []).reduce(
    (s, it) => s + (Number(it.qty) || 0) * (Number(it.rate) || 0),
    0
  );
  const taxAmount = subtotal * ((Number(inv.taxRate) || 0) / 100);
  const discount = Number(inv.discount) || 0;
  const total = Math.max(0, subtotal + taxAmount - discount);
  return { subtotal, taxAmount, discount, total };
};

const effectiveStatus = (inv) => {
  if (inv.status === "paid" || inv.status === "draft") return inv.status;
  if (inv.dueDate && inv.dueDate < todayISO()) return "overdue";
  return inv.status;
};

const defaultData = (username, company) => ({
  profile: {
    company: company || "Digital Bunches",
    email: "digitalbunches@gmail.com",
    phone: "+91-8094644444",
    address: "Jaipur, Rajasthan, India",
    currency: "INR",
  },
  clients: [],
  invoices: [],
});

const monogram = (name) => {
  if (!name) return "DB";
  const trimmed = name.trim();
  const parts = trimmed.split(/\s+/);
  if (parts.length > 1) return (parts[0][0] + parts[1][0]).toUpperCase();
  // single-word / camelCase names (e.g. "DigitalBunches") -> first letter + next capital
  const rest = trimmed.slice(1).match(/[A-Z]/);
  if (rest) return (trimmed[0] + rest[0]).toUpperCase();
  return trimmed.slice(0, 2).toUpperCase();
};

/* ------------------------------------------------------------------ */
/* Logo: loads the real Digital Bunches logo, falls back to monogram   */
/* ------------------------------------------------------------------ */

function Logo({ company, height = 32, chip = false }) {
  const [failed, setFailed] = useState(false);
  if (failed) {
    return (
      <div className="brand-mark" style={{ width: height, height }}>
        {monogram(company)}
      </div>
    );
  }
  const img = (
    <img
      src={LOGO_URL}
      alt={company || "Digital Bunches"}
      style={{ height, width: "auto", display: "block" }}
      onError={() => setFailed(true)}
    />
  );
  return chip ? <span className="logo-chip">{img}</span> : img;
}

/* ------------------------------------------------------------------ */
/* Root app                                                             */
/* ------------------------------------------------------------------ */

export default function App() {
  const [initializing, setInitializing] = useState(true);
  const [theme, setTheme] = useState("light");
  const [currentUser, setCurrentUser] = useState(null);
  const [appData, setAppData] = useState(null);
  const [view, setView] = useState("auth");
  const [editingInvoiceId, setEditingInvoiceId] = useState(null);
  const [previewInvoiceId, setPreviewInvoiceId] = useState(null);
  const [autoPrint, setAutoPrint] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = useCallback((msg) => {
    setToast(msg);
    window.clearTimeout(showToast._t);
    showToast._t = window.setTimeout(() => setToast(null), 2600);
  }, []);

  useEffect(() => {
    let unsub;
    (async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        await loadUserData(session.user);
      }
      setInitializing(false);
    })();

    // Keep the app in sync if the session changes in another tab, or expires.
    const { data: listener } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === "SIGNED_OUT") {
        setCurrentUser(null);
        setAppData(null);
        setView("auth");
      }
    });
    unsub = () => listener.subscription.unsubscribe();
    return () => unsub && unsub();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function loadUserData(user) {
    let data = await loadAppData(user.id);
    if (!data) {
      data = defaultData(user.email);
      await createAppData(user.id, data);
    }
    setAppData(data);
    setCurrentUser(user);
    setView("dashboard");
  }

  const persist = useCallback(
    async (next) => {
      setAppData(next);
      if (currentUser) {
        try {
          await saveAppData(currentUser.id, next);
        } catch (e) {
          showToast("Couldn't save — check your connection.");
        }
      }
    },
    [currentUser, showToast]
  );

  async function handleAuth({ mode, email, password, company, setError, setNotice }) {
    email = (email || "").trim();
    password = password || "";
    if (!email || !password) {
      setError("Enter an email and password.");
      return;
    }

    if (mode === "signup") {
      const { data, error } = await supabase.auth.signUp({ email, password });
      if (error) {
        setError(error.message);
        return;
      }
      if (data.session && data.user) {
        const initial = defaultData(email, company);
        await createAppData(data.user.id, initial);
        setAppData(initial);
        setCurrentUser(data.user);
        setView("dashboard");
      } else {
        // Email confirmation is on for this Supabase project — no session yet.
        setNotice("Check your inbox to confirm your account, then log in.");
      }
    } else {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password });
      if (error) {
        setError(error.message);
        return;
      }
      await loadUserData(data.user);
    }
  }

  async function handleLogout() {
    await supabase.auth.signOut();
    setCurrentUser(null);
    setAppData(null);
    setView("auth");
  }

  if (initializing) {
    return (
      <Shell theme={theme}>
        <div className="splash">
          <Logo company="Digital Bunches" height={44} />
        </div>
      </Shell>
    );
  }

  if (!currentUser || !appData) {
    return (
      <Shell theme={theme}>
        <AuthScreen onAuth={handleAuth} />
      </Shell>
    );
  }

  const invoice = editingInvoiceId
    ? appData.invoices.find((i) => i.id === editingInvoiceId)
    : null;
  const previewInvoice = previewInvoiceId
    ? appData.invoices.find((i) => i.id === previewInvoiceId)
    : null;

  return (
    <Shell theme={theme}>
      <div className="app-frame">
        {view !== "invoiceForm" && view !== "invoicePreview" && (
          <Sidebar
            view={view}
            setView={setView}
            company={appData.profile.company}
            username={currentUser?.email}
            theme={theme}
            setTheme={setTheme}
            onLogout={handleLogout}
          />
        )}

        <main className={`main-area ${view === "invoicePreview" ? "main-area--print" : ""}`}>
          {view === "dashboard" && (
            <Dashboard
              data={appData}
              onNew={() => {
                setEditingInvoiceId(null);
                setView("invoiceForm");
              }}
              onOpenInvoice={(id) => {
                setPreviewInvoiceId(id);
                setView("invoicePreview");
              }}
              onSeeAll={() => setView("invoices")}
            />
          )}

          {view === "invoices" && (
            <InvoiceList
              data={appData}
              onNew={() => {
                setEditingInvoiceId(null);
                setView("invoiceForm");
              }}
              onEdit={(id) => {
                setEditingInvoiceId(id);
                setView("invoiceForm");
              }}
              onView={(id) => {
                setPreviewInvoiceId(id);
                setView("invoicePreview");
              }}
              onPrint={(id) => {
                setPreviewInvoiceId(id);
                setAutoPrint(true);
                setView("invoicePreview");
              }}
              onDelete={(id) => {
                const next = { ...appData, invoices: appData.invoices.filter((i) => i.id !== id) };
                persist(next);
                showToast("Invoice deleted.");
              }}
              onMarkPaid={(id) => {
                const next = {
                  ...appData,
                  invoices: appData.invoices.map((i) =>
                    i.id === id ? { ...i, status: "paid", paidDate: todayISO() } : i
                  ),
                };
                persist(next);
                showToast("Marked as paid.");
              }}
            />
          )}

          {view === "invoiceForm" && (
            <InvoiceForm
              data={appData}
              invoice={invoice}
              onCancel={() => setView(invoice ? "invoices" : "dashboard")}
              onSave={(inv, andSend) => {
                const exists = appData.invoices.some((i) => i.id === inv.id);
                const invoices = exists
                  ? appData.invoices.map((i) => (i.id === inv.id ? inv : i))
                  : [...appData.invoices, inv];
                persist({ ...appData, invoices });
                showToast(andSend ? "Invoice sent." : "Invoice saved.");
                setEditingInvoiceId(inv.id);
                setPreviewInvoiceId(inv.id);
                setView(andSend ? "invoicePreview" : "invoices");
              }}
              onAddClient={(client) => {
                const next = { ...appData, clients: [...appData.clients, client] };
                persist(next);
                return client;
              }}
            />
          )}

          {view === "invoicePreview" && previewInvoice && (
            <InvoicePreview
              invoice={previewInvoice}
              profile={appData.profile}
              client={appData.clients.find((c) => c.id === previewInvoice.clientId)}
              autoPrint={autoPrint}
              onAutoPrinted={() => setAutoPrint(false)}
              onBack={() => setView("invoices")}
              onEdit={() => {
                setEditingInvoiceId(previewInvoice.id);
                setView("invoiceForm");
              }}
              onMarkPaid={() => {
                const next = {
                  ...appData,
                  invoices: appData.invoices.map((i) =>
                    i.id === previewInvoice.id ? { ...i, status: "paid", paidDate: todayISO() } : i
                  ),
                };
                persist(next);
                showToast("Marked as paid.");
              }}
            />
          )}

          {view === "clients" && (
            <ClientsView
              data={appData}
              onSave={(client) => {
                const exists = appData.clients.some((c) => c.id === client.id);
                const clients = exists
                  ? appData.clients.map((c) => (c.id === client.id ? client : c))
                  : [...appData.clients, client];
                persist({ ...appData, clients });
                showToast("Client saved.");
              }}
              onDelete={(id) => {
                persist({ ...appData, clients: appData.clients.filter((c) => c.id !== id) });
                showToast("Client removed.");
              }}
            />
          )}

          {view === "settings" && (
            <SettingsView
              profile={appData.profile}
              username={currentUser?.email}
              onSave={(profile) => {
                persist({ ...appData, profile });
                showToast("Settings saved.");
              }}
            />
          )}
        </main>
      </div>

      {toast && <div className="toast">{toast}</div>}
    </Shell>
  );
}

/* ------------------------------------------------------------------ */
/* Shell: theming + global styles                                      */
/* ------------------------------------------------------------------ */

function Shell({ theme, children }) {
  return (
    <div data-theme={theme} className="folio-root">
      <style>{CSS}</style>
      {children}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Auth screen                                                         */
/* ------------------------------------------------------------------ */

function AuthScreen({ onAuth }) {
  const [mode, setMode] = useState("login");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [company, setCompany] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [busy, setBusy] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setError("");
    setNotice("");
    setBusy(true);
    await onAuth({ mode, email, password, company, setError, setNotice });
    setBusy(false);
  };

  return (
    <div className="auth-screen">
      <div className="auth-hero">
        <svg viewBox="0 0 400 500" className="auth-hero-svg" aria-hidden="true">
          {Array.from({ length: 14 }).map((_, i) => (
            <line key={i} x1="24" y1={70 + i * 30} x2="376" y2={70 + i * 30} className="ledger-line" />
          ))}
          <circle cx="40" cy="70" r="3" className="ledger-dot" />
          <circle cx="40" cy="220" r="3" className="ledger-dot" />
          <circle cx="40" cy="400" r="3" className="ledger-dot" />
        </svg>
        <div className="auth-hero-copy">
          <Logo company="Digital Bunches" height={40} chip />
          <div className="auth-wordmark">Digital Bunches</div>
          <p className="auth-tagline">Let's build a brand and spread it.</p>
          <p className="auth-sub">
            Invoice retainers, campaigns, and one-off deliverables for SEO, SMO,
            PPC, web, and branding work — and keep every client's spend in one place.
          </p>
        </div>
      </div>

      <div className="auth-panel">
        <form className="auth-form" onSubmit={submit}>
          <div className="auth-tabs">
            <button
              type="button"
              className={`auth-tab ${mode === "login" ? "auth-tab--active" : ""}`}
              onClick={() => { setMode("login"); setError(""); setNotice(""); }}
            >
              Log in
            </button>
            <button
              type="button"
              className={`auth-tab ${mode === "signup" ? "auth-tab--active" : ""}`}
              onClick={() => { setMode("signup"); setError(""); setNotice(""); }}
            >
              Create account
            </button>
          </div>

          <label className="field">
            <span className="field-label">Email</span>
            <input
              className="field-input"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@digitalbunches.com"
              autoComplete="email"
            />
          </label>

          {mode === "signup" && (
            <label className="field">
              <span className="field-label">Business name</span>
              <input
                className="field-input"
                value={company}
                onChange={(e) => setCompany(e.target.value)}
                placeholder="Digital Bunches"
              />
            </label>
          )}

          <label className="field">
            <span className="field-label">Password</span>
            <input
              className="field-input"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              autoComplete={mode === "signup" ? "new-password" : "current-password"}
              minLength={6}
            />
          </label>

          {error && <div className="auth-error">{error}</div>}
          {notice && <div className="auth-notice">{notice}</div>}

          <button className="btn btn--primary btn--block" type="submit" disabled={busy}>
            {busy ? "One moment…" : mode === "signup" ? "Create account" : "Log in"}
            <ArrowRight size={16} />
          </button>

          <p className="auth-footnote">
            Your account and invoices are stored securely in your own Supabase
            project — private to you, not shared with anyone else.
          </p>
        </form>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Sidebar                                                              */
